message.content:
{
  "title": "The Mirror Passage",
  "gate_token": "KElX8R_eRzVkd_mSQOBBPg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds the map under a broken arch.",
      "visual_description": "Ruined gate with crumbled stone arch and faded royal banners hanging limp. Mara the Cartographer spreads a large ink map on the ground, compass in hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Glass Diver polishes his helmet, reflecting torchlight.",
      "visual_description": "Glass Diver kneels by a puddle, rubbing his diving helmet with a cloth. The helmet's reflection glints with distant flames from the ruined city.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp flickers and whispers a warning.",
      "visual_description": "Oracle Lamp sits on a fallen pillar, its single eye glowing in the flame. A faint whisper echoes off broken walls.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Sleeping Tax Collector snores on a pile of ledgers.",
      "visual_description": "Inside a crumbling building, the Sleeping Tax Collector rests head on a thick ledger, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "Tin Fox scampers across a collapsed courtyard.",
      "visual_description": "Tin Fox darts over rubble in a moonlit courtyard, key-wind tail twitching, blue glass eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara points toward a cursed tower on the horizon.",
      "visual_description": "Mara stands on a broken bridge, pointing at a dark, twisted tower behind iron gates. Faint magical runes pulse on its walls.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver peers through a shattered window into the tower.",
      "visual_description": "Glass Diver leans close to a cracked window pane, his helmet fogging slightly as he looks into the tower's dark interior.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp lights a corridor of magic doors.",
      "visual_description": "A long hallway lined with ornate doors glowing with runes. Oracle Lamp hovers, casting shifting shadows on each door.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Sleeping Tax Collector is jostled awake by Tin Fox.",
      "visual_description": "Tin Fox nudges the Sleeping Tax Collector's leg with its metal snout. The Tax Collector stirs, groggy, stamps fluttering.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara traces a secret route on her map.",
      "visual_description": "Mara kneels by a brazier, her finger moving along a hidden path drawn in invisible ink, the lines glowing faintly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver swims through a window into a locked room.",
      "visual_description": "Glass Diver presses against a window and passes through like water, emerging into a chamber with armored mannequins standing rigid.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp burns brighter as a warning hisses.",
      "visual_description": "Oracle Lamp's flame swells, casting red light on the walls. A sibilant whisper warns of armored patrols approaching.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Sleeping Tax Collector sleepwalks through a secret tunnel.",
      "visual_description": "Sleeping Tax Collector shuffles, eyes closed, through a narrow tunnel lit by glowing moss, clutching his ledger.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox discovers a hidden cache of keys.",
      "visual_description": "Tin Fox digs in rubble, uncovering a small iron box filled with rusted keys of various shapes, blue eyes glinting.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Mara and Glass Diver reunite at the tower base.",
      "visual_description": "Mara and Glass Diver meet at the cursed tower's foundation. Dust swirls around as she points upward, he nods.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The group assembles for the final push.",
      "visual_description": "All five characters gather: Mara, Glass Diver, Oracle Lamp, Sleeping Tax Collector, and Tin Fox, standing before a massive iron-banded door.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They burst through the door onto a crumbling bridge.",
      "visual_description": "The heavy door slams open, revealing a long stone bridge over a chasm. Clouds part, moonlight illuminating the escape route.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The rescue crosses the bridge as dawn breaks.",
      "visual_description": "The five figures hurry across the bridge as the sky lightens. Behind them, the ruined city's towers crumble, banners falling.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

